import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void batch_norm_forward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int N, int C, int H, int W, float eps)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * C * H * W;
    if (idx >= total_size) return;

    // Calculate NCHW indices
    int n = idx / (C * H * W);
    int c = (idx / (H * W)) % C;
    int hw = idx % (H * W);

    float x_val = x[idx];
    float mean_val = mean[c];
    float var_val = var[c];
    float gamma_val = gamma[c];
    float beta_val = beta[c];

    out[idx] = (x_val - mean_val) * rsqrtf(var_val + eps) * gamma_val + beta_val;
}

torch::Tensor batch_norm_forward_cuda(
    torch::Tensor x,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps)
{
    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);

    auto out = torch::empty_like(x);

    int total_size = N * C * H * W;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    batch_norm_forward_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W, eps
    );

    return out;
}
"""

bn_forward_cpp_source = r"""
torch::Tensor batch_norm_forward_cuda(
    torch::Tensor x,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps);
"""

bn_ext = load_inline(
    name="bn_ext",
    cpp_sources=bn_forward_cpp_source,
    cuda_sources=bn_source,
    functions=["batch_norm_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom BatchNorm2d implementation with a CUDA kernel.
    """
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.momentum = 0.1
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.training:
            mean = x.mean(dim=(0, 2, 3))
            var = x.var(dim=(0, 2, 3), unbiased=False)
            with torch.no_grad():
                self.running_mean.mul_(1 - self.momentum).add_(mean, alpha=self.momentum)
                self.running_var.mul_(1 - self.momentum).add_(var, alpha=self.momentum)
            return bn_ext.batch_norm_forward_cuda(
                x, mean, var, self.weight, self.bias, self.eps
            )
        else:
            return bn_ext.batch_norm_forward_cuda(
                x, self.running_mean, self.running_var, self.weight, self.bias, self.eps
            )


